  "agConfirmEraseAllEverywhere": "DANGER : Cette action supprimera définitivement TOUS les élèves de toute l'application (y compris l'Éditeur de groupes et les listes principales). Confirmer ?",
  "agAllStudentsArchived": "Tous les dossiers élèves ont été archivés et la vue réinitialisée.",
