  "importDestAdminGroups": "Maîtrise de groupe",
  "importDestAdminGroupsDesc": "Importer les données des élèves pour alimenter les colonnes de Maîtrise de groupe",
  "importAdminGroupPickLabel": "Groupe administratif cible",
