  "gsRefCritBlankName": "Un nom vide est enregistré comme Critère {n}.",
  "gsMenuPrintSemGradesLabel": "Imprimer les notes {sem}",
  "gsTestMetaDesc": "Feuille de test modifiable avec critères pondérés. Le coefficient du test est utilisé dans les moyennes de période.",
  "gsGradingManualTotalPts": "Total de points disponibles : {total}.",
  "gsGradingManualNeedCrit": "Le mode points nécessite des critères avec des points. Ajoutez des critères.",
  "gsGradingManualSetPct": "Définissez les pourcentages minimaux pour chaque note.",
  "gsNoCriteriaYet": "Aucun critère.",
  "gsTestTourNeedTest": "Ouvrez d'abord un test pour démarrer la visite.",
  "tutGs1Title": "En-tête du test",
  "tutGs1Text": "Affiche le nom de la classe, la période et l'identifiant du test. La ligne en dessous rappelle que la feuille utilise des critères pondérés.",
  "tutGs2Title": "Actions",
  "tutGs2Text": "Options du test : panneau complet (notation, critères, infos). Critères de référence : voir tous les critères et barèmes. Appliquer les critères : calcule automatiquement les notes depuis les totaux. Imprimer : exporte ou imprime. Dupliquer / Importer : copie la configuration d'un autre test. Supprimer / Effacer : supprime ou réinitialise le test.",
  "tutGs3Title": "Puces de configuration",
  "tutGs3Text": "Cliquez sur une puce pour ouvrir son éditeur. Coefficient : poids du test dans la moyenne de période, ou poids fixe en %. Barème : seuils de notation (ex. 60% → 4). Critères : sections évaluées avec points max et coefficients. Infos du test : nom, date, contenu, type et seuil de la prochaine note.",
  "tutGs4Title": "Colonnes du tableau",
  "tutGs4Text": "Colonnes fixes : indice, prénom, nom de l'élève. Colonnes calculées : Note (selon le barème), Δ Note suivante (points manquants pour la note au-dessus), Observations (texte libre), total des Points et Temps. Les colonnes de critères suivent — cliquez sur un en-tête pour modifier son nom, ses points max, son coefficient ou son statut bonus.",
  "tutGs5Title": "Saisie des notes",
  "tutGs5Text": "Chaque ligne correspond à un élève. Cliquez sur une cellule d'une colonne de critère pour saisir la note. Tab passe à la cellule suivante. La Note et les Points se recalculent instantanément. La cellule Observations accepte du texte libre. Cliquez sur le nom d'un élève pour ouvrir sa fiche.",
  "tutGsM1Title": "Infos du test",
  "tutGsM1Text": "Donnez un nom au test (affiché dans les en-têtes de colonnes), une date, le contenu (chapitres ou unités couverts) et le type (Écrit, Oral, Quiz…). Les puces Période déplacent le test dans un autre semestre. Seuil de prochaine note : les élèves à moins de ce nombre de points de la note supérieure sont surlignés en vert. Mettez 0 pour désactiver.",
  "tutGsM2Title": "Coefficient",
  "tutGsM2Text": "Détermine le poids de ce test dans la moyenne de période. Mode coefficient : pondération proportionnelle — un coefficient 2 compte deux fois plus qu'un coefficient 1. Poids fixe % : ce test représente toujours exactement ce pourcentage de la moyenne, indépendamment du nombre d'autres tests.",
  "tutGsM3Title": "Barème de notation",
  "tutGsM3Text": "Définit la conversion des points en notes. Formule : entrez un seuil en % pour la note 4 et choisissez un modèle — tous les autres seuils sont calculés proportionnellement. % manuels par note : définissez manuellement chaque seuil minimum. Points manuels par note : définissez le nombre minimum de points par note directement — utile quand le total est fixé. Le sélecteur de modèle charge des préréglages depuis les données de référence.",
  "tutGsM4Title": "Critères",
  "tutGsM4Text": "Les critères sont les sections évaluées du test (ex. Vocabulaire, Grammaire, Expression). Glissez les lignes pour réordonner ; cliquez pour modifier. Max : points maximum. Coeff : coefficient par critère appliqué avant l'addition au total. Bonus : ne compte pas dans le total possible — ne peut qu'augmenter le score. Le préréglage charge un modèle sauvegardé. Le champ × ajoute plusieurs critères identiques en une fois.",
  "tutGsM5Title": "Enregistrer et fermer",
  "tutGsM5Text": "Enregistrer applique tous les changements et recalcule les notes immédiatement. Fermer annule les modifications non sauvegardées. La modification des critères conserve les notes existantes pour ceux dont l'identifiant est inchangé ; les nouveaux critères démarrent vides et les critères supprimés perdent leurs notes.",
  "tutGsM6Title": "Aperçu des notes",
  "tutGsMChipsText": "Configurez la banque d'étiquettes d'observation et les sections prédéfinies pour cette épreuve.",
  "tutGsM6Text": "Visualisez comment le total des points se transforme en notes (1.0 à 6.0) selon vos paramètres.",
