  "tutGsC1Title": "Vue d'ensemble du carnet de notes",
  "tutGsC1Text": "Bienvenue dans le Carnet de notes ! Cette page principale affiche toutes vos fiches de classe ainsi que les actions rapides pour gérer les devoirs et les données de référence.",
  "tutGsC2Title": "Grille des classes",
  "tutGsC2Text": "Chaque carte présente le résumé d'une classe avec l'effectif, le nombre de devoirs et la moyenne. Cliquez sur une carte pour ouvrir sa matrice complète de notes.",
  "tutGsC3Title": "Ajouter une classe & un devoir",
  "tutGsC3Text": "Utilisez « + Ajouter une classe » pour configurer une nouvelle classe, ou « Ajouter un test » pour créer une nouvelle évaluation.",
  "tutGsC4Title": "Export & Import JSON",
  "tutGsC4Text": "Exporter JSON sauvegarde toutes les classes, notes, critères et barèmes. Importer JSON permet de restaurer ou de charger des fichiers de données.",
  "tutGsC5Title": "Éditer critères & barèmes (En détail)",
  "tutGsC5Text": "Banque centrale pour vos standards d'évaluation !\n• Critères de correction : définissez des rubriques réutilisables (Vocabulaire, Grammaire, etc.) avec points max par défaut, coefficients et descripteurs de notes.\n• Modèles de barèmes : configurez les courbes de notation et les seuils en % pour le calcul automatique des notes.\n• Puces d'observation : personnalisez les étiquettes de commentaires rapides pour les évaluations.\nLes modifications mettent à jour les modèles dans toute l'application.",
  "tutGsC6Title": "Activité de correction & Chronologie",
  "tutGsC6Text": "Suivez le nombre d'élèves corrigés aujourd'hui, cette semaine, ce mois et cette année, le temps passé, les copies restantes et une chronologie interactive.",
  "tutGsS1Title": "En-tête de synthèse de classe",
  "tutGsS1Text": "Affiche le nom de la classe et les instructions. Cette vue constitue le relevé de notes principal pour l'ensemble des périodes de la classe.",
  "tutGsS2Title": "Filtres de période",
  "tutGsS2Text": "Basculez entre Semestre 1 (S1), Semestre 2 (S2) ou Année complète. Le changement de période recalcule dynamiquement les colonnes et les moyennes.",
  "tutGsS3Title": "Matrice des notes",
  "tutGsS3Text": "Liste les élèves avec leurs notes de devoirs (T1, T2...), moyennes calculées et statistiques de classe. Cliquez sur l'en-tête d'un devoir (T1, T2...) pour ouvrir sa feuille détaillée.",
  "tutGsS4Title": "Ajouter & importer des tests",
  "tutGsS4Text": "Ajouter un test crée une nouvelle colonne d'évaluation pour cette classe. Importer un test copie la configuration d'un test depuis une autre classe.",
  "tutGsS5Title": "Gestion de la classe & des élèves",
  "tutGsS5Text": "Ajouter un élève insère un nouvel élève sur la feuille. Éditer la classe modifie le nom, les dates de période ou les coefficients de semestre.",
  "tutGsS6Title": "Export & Import de notes",
  "tutGsS6Text": "Exporte les synthèses en PDF, HTML, DOCX, CSV ou XLSX. Importer des notes permet d'intégrer des notes depuis des fichiers tableurs.",
  "tutGsR1Title": "Catégories de données de référence",
  "tutGsR1Text": "Basculez entre les onglets Critères de correction, Modèles de barèmes et Puces d'observation pour gérer vos modèles réutilisables.",
  "tutGsR2Title": "Modèles de critères de correction",
  "tutGsR2Text": "Ajoutez, renommez ou dupliquez des critères d'évaluation. Définissez les points max, coefficients et descripteurs par défaut.",
  "tutGsR3Title": "Modèles de barèmes de notation",
  "tutGsR3Text": "Configurez des modèles de barèmes personnalisés et les seuils minimaux en % pour le calcul automatique des notes.",
  "tutGsR5Title": "Onglet Puces d'observation",
  "tutGsR5Text": "Configurez les catégories et étiquettes d'observation personnalisées à clic rapide pour enrichir les commentaires d'évaluation des élèves.",
  "tutGsR4Title": "Enregistrer les données de référence",
  "tutGsR4Text": "Cliquez sur Enregistrer pour sauvegarder les modifications dans user/correction-criteria.js et user/grade-scale-models.js.",
