  "helpTipFilters1": "<strong>Niveau, Thème, Type</strong> — utilisez ces filtres pour réduire le pool de mots avant de commencer un jeu. Sélectionnez plusieurs valeurs ; seuls les mots correspondant à <em>tous les filtres actifs</em> apparaîtront.",
