  "lcPillsGuideSub": "Guide pour débutants pour structurer efficacement les phases de cours et les regroupements d'élèves.",
  "lcPillsGuideTip": "Astuce : Survolez une pastille d'activité ou de modalité dans la frise pour voir son explication.",
  "lcTabActivities": "Types d'activités",
  "lcTabModes": "Modalités d'interaction",
  "lcPillWhenToUse": "Quand l'utiliser :",
  "lcPillPedagogy": "Objectif pédagogique :",
  "lcActWarmUpDesc": "Courte activité de démarrage (3 à 5 min) en début de séance pour mobiliser les élèves, réactiver les prérequis et installer un climat propice au travail.",
  "lcAct_warm_up_when": "5 premières minutes ; rituel d'entrée, réactivation rapide des acquis.",
  "lcActDirectInstructionDesc": "Présentation explicite de nouvelles notions par l'enseignant, modélisation de démarches, règles ou exemples guidés (10 à 15 min).",
  "lcAct_direct_instruction_when": "Introduction d'un nouvel objectif, d'une règle, d'une formule ou d'une méthode.",
  "lcActGuidedPracticeDesc": "Les élèves s'exercent avec l'accompagnement direct de l'enseignant, un étayage progressif et des rétroactions immédiates (« Je fais, Nous faisons, Tu fais »).",
  "lcAct_guided_practice_when": "Directement après le cours pour consolider la compréhension et corriger les erreurs.",
  "lcActIndependentWorkDesc": "Les élèves appliquent les notions individuellement en autonomie sur des exercices, lectures ou productions sans aide directe.",
  "lcAct_independent_work_when": "Après la pratique guidée lorsque les notions sont comprises ; permet à l'enseignant de circuler et différencier.",
  "lcActGroupActivityDesc": "Tâche collective où les élèves résolvent un problème complexe, mènent un projet ou enquêtent avec des rôles définis au sein du groupe.",
  "lcAct_group_activity_when": "Résolution de problèmes complexes, tâches complexes, travail par projet ou méthode jigsaw.",
  "lcActDiscussionDesc": "Échange collectif structuré, cercle socratique ou débat où les élèves expriment leurs arguments, écoutent et confrontent leurs opinions.",
  "lcAct_discussion_when": "Analyse critique, débats d'idées, questions éthiques ou développement de l'expression orale.",
  "lcActAssessmentDesc": "Vérification formative rapide de la compréhension (quiz éclair, ardoises, sondage) pour mesurer les acquis et diagnostiquer les besoins.",
  "lcAct_assessment_when": "Point d'étape en milieu de cours, avant un palier de difficulté, ou diagnostic de remédiation.",
  "lcActPlenaryDesc": "Conclusion de la séance (5 à 10 min) pour récapituler les points essentiels, vérifier l'atteinte des objectifs et recueillir un billet de sortie.",
  "lcAct_plenary_when": "5 à 10 dernières minutes pour ancrer les acquis et préparer la séance suivante.",
  "lcModeWholeClassDesc": "Tous les élèves participent simultanément en tant que groupe unique (ex. lecture offerte, document partagé, remue-méninges collectif).",
  "lcMode_whole_class_when": "Focalisation commune, consignes générales, visionnage partagé ou rituel collectif.",
  "lcModeTeacherLedDesc": "L'enseignant pilote la séance au tableau ou à l'écran, explicite les notions, pose des questions et orchestre les interventions.",
  "lcMode_teacher_led_when": "Cours explicite, démonstration au tableau, apport de notions théoriques.",
  "lcModeIndividualDesc": "Chaque élève travaille seul et en silence à sa place, favorisant une concentration soutenue et l'autonomie personnelle.",
  "lcMode_individual_when": "Lecture silencieuse, rédaction individuelle, exercices d'entraînement ou évaluations.",
  "lcModePairsDesc": "Les élèves collaborent en binômes (« Penser-Échanger-Partager », relecture croisée, dialogues). Maximise le temps de parole en confiance.",
  "lcMode_pairs_when": "Échanges flash (« Turn & Talk »), correction mutuelle, dialogue en langue vivante.",
  "lcModeSmallGroupsDesc": "Équipes restreintes de 3 à 4 élèves coopérant avec des rôles distribués (porte-parole, gestionnaire du temps, secrétaire, animateur).",
  "lcMode_small_groups_when": "Travail coopératif, réalisation de maquettes ou affiches, résolution de problèmes.",
  "lcModeStationsDesc": "La classe est organisée en ateliers ou îlots thématiques minutés ; les groupes circulent d'une station à l'autre.",
  "lcMode_stations_when": "Ateliers tournants, travaux pratiques scientifiques, ateliers de remédiation/approfondissement.",
